/// Every command the plugin exposes, by its Rust name. `tauri_plugin::Builder`
/// writes one `allow-*` / `deny-*` pair per entry into
/// `permissions/autogenerated/commands/`, and `permissions/default.toml` is
/// where those grants are collected.
///
/// ⚠️ **OMISSION FROM THIS LIST DOES NOT MAKE A COMMAND UNREACHABLE** — it only
/// stops that command's permission pair being GENERATED. `commands/tests.rs`'s
/// `lists_agree` is what holds the three lists together, as it does in the
/// passages plugin.
const COMMANDS: &[&str] = &[
    "narration_supported",
    "narration_pick",
    "narration_begin",
    "narration_discard_chapter",
    "narration_discard",
    "narrate_package",
    "narration_exists",
    "narration_discard_book",
    "narration_release",
];

fn main() {
    tauri_plugin::Builder::new(COMMANDS).build();
}
